<?php require_once '../config/config.php';require_admin();$title='Manage Bookings | '.APP_NAME;
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)$_POST['id'];$status=$_POST['status'];$allowed=['pending','confirmed','cancelled','checked_in','checked_out'];if(in_array($status,$allowed,true)){$s=db()->prepare("UPDATE bookings SET status=? WHERE id=?");$s->execute([$status,$id]);flash('success','Booking updated.');}redirect('bookings.php');}
$rows=db()->query("SELECT b.*,u.name,u.email,r.room_number,rt.name type_name,p.status payment_status FROM bookings b JOIN users u ON u.id=b.user_id JOIN rooms r ON r.id=b.room_id JOIN room_types rt ON rt.id=r.room_type_id LEFT JOIN payments p ON p.booking_id=b.id ORDER BY b.created_at DESC")->fetchAll();require '../partials_header.php';?>
<div class="admin-nav"><div class="container"><strong>Admin Panel</strong><a href="index.php">Dashboard</a><a href="rooms.php">Rooms</a><a href="bookings.php">Bookings</a></div></div><div class="page"><div class="container"><h1>Booking Management</h1><div class="panel table-wrap"><table class="table"><tr><th>Code</th><th>Customer</th><th>Room</th><th>Dates</th><th>Total</th><th>Payment</th><th>Status</th></tr><?php foreach($rows as $b):?><tr><td><?=e($b['booking_code'])?></td><td><?=e($b['name'])?><br><small><?=e($b['email'])?></small></td><td><?=e($b['type_name'])?> #<?=e($b['room_number'])?></td><td><?=e($b['check_in'])?> → <?=e($b['check_out'])?></td><td>NPR <?=number_format((float)$b['total_amount'])?></td><td><?=e($b['payment_status']??'pending')?></td><td><form method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="id" value="<?=$b['id']?>"><select name="status" onchange="this.form.submit()"><?php foreach(['pending','confirmed','cancelled','checked_in','checked_out'] as $st):?><option <?=$b['status']===$st?'selected':''?>><?=$st?></option><?php endforeach;?></select></form></td></tr><?php endforeach;?></table></div></div></div><?php require '../partials_footer.php'; ?>
